import re
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

from project_environment import ProjectEnv

#Imported after ProjectEnv
from src.utils import Log


class BaseScriptGenerator:
    """Shared base architecture for tools that compile and generate source files."""
    
    def __init__(self, output_rel_path: str | Path) -> None:
        # We safely resolve all generated files relative to the ROOT_DIR
        self.output_path: Path = ProjectEnv.ROOT_DIR / output_rel_path

    def _prepare_directory(self) -> None:
        """Ensures the nested target asset directories exist safely before writing."""
        self.output_path.parent.mkdir(parents=True, exist_ok=True)
        
    def _get_timestamp(self) -> str:
        """Returns a universally standardized UTC timestamp string."""
        return datetime.now(timezone.utc).strftime("%Y-%m-%d at %H:%M:%S")
    
    def _get_autogen_header(self, script_filename: str) -> str:
        """Generates the standardized terminal-style warning header with a timestamp."""
        return (
            "# ==========================================\n"
            "# THIS FILE IS AUTO-GENERATED BY A SCRIPT.\n"
            "# DO NOT EDIT THIS FILE MANUALLY.\n"
            f"# Run tools/{script_filename} to update.\n"
            f"# Generated on: {self._get_timestamp()}\n"
            "# ==========================================\n\n"
        )
        
    def write_timestamp_log(self, log_rel_path: str | Path, label: str = "Asset") -> None:
        """Writes a standardized timestamp log file for any generator tool."""
        log_path = ProjectEnv.ROOT_DIR / log_rel_path
        log_path.parent.mkdir(parents=True, exist_ok=True)

        log_path.write_text(f"{label} last updated on: {self._get_timestamp()}\n", encoding="utf-8")
        Log.info(f"Timestamp log recorded: {log_path.relative_to(ProjectEnv.ROOT_DIR)}")
        
    def _get_display_path(self, target_path: str | Path) -> str:
        """Safely generates a clean, relative path for terminal logging."""
        try:
            # Resolve resolves symlinks/relative dots, making the comparison safe
            return str(Path(target_path).resolve().relative_to(ProjectEnv.ROOT_DIR))
        except ValueError:
            # Fallback to the raw string if the path is somehow completely outside the project
            return str(target_path)
    
    def write_if_changed(self, body_content: str, script_filename: str, add_header: bool = True) -> bool:
        """ Appends the autogen header (optional), checks if the compilation introduces fresh data, 
        and updates the disk only if modification diffs are identified.
        Returns True if a file write occurred, False if skipped."""
        full_compiled_text = (self._get_autogen_header(script_filename) if add_header else "") + body_content
        self._prepare_directory()

        display_path = self._get_display_path(self.output_path)

        # SMART CACHING CHECK: Compare existing string contents against new compilation buffer
        if self.output_path.exists() and self.output_path.read_text(encoding="utf-8") == full_compiled_text:
            Log.info(f"No adjustments detected for '{display_path}'. Skipping file write.")
            return False

        # If mismatch detected, commit adjustments to the filesystem
        self.output_path.write_text(full_compiled_text, encoding="utf-8")
        Log.info(f"Baked updates to '{display_path}'.")
        return True
    
    def inject_between_markers(self, file_path: str | Path, marker_name: str, injection_content: str) -> bool:
        """ Replaces text exactly between # BEGIN {marker_name} and # END {marker_name}.
        Utilizes the base Log system to report success or errors.
        Returns True if a change was written to the file. """
        target_path = Path(file_path)
        display_path = self._get_display_path(target_path)
        if not target_path.exists():
            Log.error(f"Cannot find target file for injection: {display_path}")
            return False

        content = target_path.read_text(encoding="utf-8")
        
        # Regex to match the exact block between the specific BEGIN and END comments
        pattern = re.compile(
            rf"(# BEGIN {marker_name}\n)(.*?)(# END {marker_name})", 
            re.DOTALL
        )
        
        if not pattern.search(content):
            Log.error(f"Could not find markers for '{marker_name}' in {display_path}")
            return False
            
        # Inject the new content, preserving the marker tags themselves
        new_content = pattern.sub(rf"\g<1>{injection_content}\n\g<3>", content)
        
        # Check if we actually introduced new data
        if content != new_content:
            target_path.write_text(new_content, encoding="utf-8")
            Log.success(f"Successfully injected '{marker_name}' updates into {display_path}")
            return True
            
        Log.info(f"No marker adjustments needed for '{display_path}' ({marker_name}). Skipping injection.")
        return False
    
    def sync_init_files(self, names:list[str], init_path:Path, marker_name:str):
        """Universally synchronizes __init__.py import and export blocks using markers."""
        target_file = init_path / "__init__.py"
        separator = ",\n    "
        
        # Format and inject the import block
        import_block = f"from .{marker_name.lower()} import (\n    {separator.join(names)},\n)"
        self.inject_between_markers(target_file, f"{marker_name}_IMPORT", import_block)
        
        # Format and inject the export block (adding quotes and indents for the __all__ list)
        export_block = f"    {separator.join(f'\"{i}\"' for i in names)},"
        self.inject_between_markers(target_file, f"{marker_name}_EXPORT", export_block)
        
    @staticmethod
    def run_with_cli(tool_name: str, examples: str, generator_callback) -> None:
        """A universal interactive CLI wrapper for targeting specific files/folders."""
        import sys
        args = sys.argv[1:]
        
        if args:
            generator_callback(args)
            return

        print(f"--- Python Plant Sim {tool_name} Generator ---")
        print("Enter a file or folder path inside 'src' (or press Enter for whole project)")
        print(f"Examples: {examples}")
        
        while True:
            user_input = input("\n> Path (or 'q' to quit, Enter for all): ").strip()
            
            if user_input.lower() == 'q':
                print("Exiting generator.")
                break
            elif user_input == "":
                generator_callback(["."])
                break
            else:
                paths = [p.strip() for p in user_input.split(',') if p.strip()]
                if paths:
                    generator_callback(paths)
    
    @staticmethod
    def generate_all(tools_dir: str = "tools") -> None:
        """Scans the specified directory for 'generate_*.py' scripts and executes them sequentially."""
        Log.info(f"Master Build Started: Scanning '{ProjectEnv.TOOLS_DIR.name}' for generation pipelines...\n")
        
        # Gather all valid generation scripts
        scripts = sorted(
            f for f in ProjectEnv.TOOLS_DIR.iterdir() 
            if f.is_file() and f.name.startswith("generate_") and f.name.endswith(".py")
        )
        
        if not scripts:
            Log.info("No generation scripts found.")
            return

        # Sort alphabetically so they run in a predictable sequence
        scripts.sort()
        
        for script in scripts:
            Log.info(f"-> Launching: {script}")
            Log.divider(40)
            
            # Run the file using the exact same python execution environment
            result = subprocess.run([sys.executable, str(script), "."], check=False)
            Log.divider(40)
            if result.returncode == 0:
                Log.success(f"-> Completed: {script} Successfully.\n")
            else:
                Log.error(f"-> WARNING: {script} exited with error code {result.returncode}.\n")

        Log.success("Master Build Pipeline finished completely.")
        
if __name__ == "__main__":
    # Tells the engine to look inside the "tools" folder and execute everything
    BaseScriptGenerator.generate_all(tools_dir="tools")